<style>
.ec96-article{background:#f4f8f5;color:#183b2c;padding:28px 0 72px}.ec96-article-wrap{width:min(1240px,calc(100% - 40px));margin:auto}.ec96-article a{color:inherit;text-decoration:none}.ec96-article a:hover{color:#007e42}.ec96-article a:focus-visible,.ec96-article button:focus-visible,.ec96-article summary:focus-visible{outline:3px solid #e89520;outline-offset:4px}.ec96-article-breadcrumb,.ec96-article-meta{display:flex;gap:12px;flex-wrap:wrap;font-size:13px;color:#587365}.ec96-article-heading{max-width:950px;padding:32px 0}.ec96-article-kicker{font-size:12px;text-transform:uppercase;letter-spacing:2px;font-weight:700;color:#007e42}.ec96-article-heading h1{font-size:clamp(28px,3.4vw,44px);line-height:1.25;margin:14px 0 18px;overflow-wrap:anywhere}.ec96-article-heading>p{font-size:17px;line-height:1.8;margin:20px 0 0;color:#536b5f}.ec96-article-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:32px;align-items:start}.ec96-article-layout>*,.ec96-article-sidebar{min-width:0}.ec96-article-paper{padding:28px;background:#fff;border:1px solid #dfebe3;border-radius:18px}.ec96-article-cover{margin:-28px -28px 28px;overflow:hidden;border-radius:18px 18px 0 0}.ec96-article-cover img{width:100%;max-height:480px;aspect-ratio:16/9;object-fit:cover;display:block}.ec96-article-toc{background:#eef6f0;border:1px solid #dceadf;padding:18px 22px;border-radius:12px;margin-bottom:26px}.ec96-article [hidden]{display:none!important}.ec96-article-toc summary{cursor:pointer;font-weight:700}.ec96-article-toc ol{margin:12px 0 0;padding-left:20px}.ec96-article-toc li{padding:5px 0;line-height:1.6}.ec96-article-body{font-size:16px;line-height:1.95;color:#354d40;overflow-wrap:anywhere;overflow-x:auto}.ec96-article-body h2,.ec96-article-body h3{line-height:1.4;color:#173e2b;margin:30px 0 14px;scroll-margin-top:120px}.ec96-article-body h2{font-size:24px}.ec96-article-body h3{font-size:20px}.ec96-article-body img,.ec96-article-body video,.ec96-article-body iframe{max-width:100%;height:auto}.ec96-article-body a{color:#007e42;border-bottom:1px solid #91b89f}.ec96-article-body blockquote{border-left:3px solid #007e42;margin:24px 0;padding:12px 22px;background:#f4f8f5}.ec96-article-tags{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.ec96-article-tags a{background:#eef6f0;padding:6px 12px;border-radius:20px}.ec96-article-share{border-top:1px solid #e1ebe4;padding-top:24px;margin-top:28px;display:flex;gap:14px;flex-wrap:wrap;align-items:center;font-size:13px}.ec96-article-share button{background:#007e42;color:white;border:0;border-radius:24px;padding:12px 20px;font:inherit;cursor:pointer}.ec96-article-share input{width:100%;min-width:0;padding:12px;border:1px solid #bacebf}.ec96-article-sidebar>section{padding:24px;border-radius:16px;margin-bottom:24px}.ec96-article-latest{background:white;border:1px solid #dfebe3}.ec96-article-sidebar h2,.ec96-article-related>h2{font-size:23px;line-height:1.4;margin:0 0 20px}.ec96-article-latest-item{display:flex;gap:14px;align-items:flex-start;border-bottom:1px solid #e6eee8;padding:18px 0}.ec96-article-latest-item img{width:76px;height:76px;object-fit:cover;border-radius:8px;flex-shrink:0}.ec96-article-latest-item h3{font-size:14px;line-height:1.6;margin:0 0 7px;overflow-wrap:anywhere}.ec96-article-latest-item time{font-size:12px;color:#6d8075}.ec96-article-all{display:inline-block;margin-top:20px;font-weight:700;font-size:14px}.ec96-article-promo{background:#e1efe5}.ec96-article-promo p{font-size:15px;line-height:1.8}.ec96-article-promo a{display:block;font-size:14px;font-weight:700;line-height:1.6}.ec96-article-related{margin-top:38px}.ec96-article-related-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.ec96-article-card{border:1px solid #dfebe3;border-radius:14px;overflow:hidden;background:white}.ec96-article-card>img{width:100%;aspect-ratio:3/2;object-fit:cover;display:block}.ec96-article-card>div{padding:18px}.ec96-article-card h3{font-size:16px;line-height:1.6;margin:0 0 16px;overflow-wrap:anywhere}.ec96-article-card span{font-size:12px;font-weight:700;color:#007e42}
@media(max-width:1000px){.ec96-article-layout{grid-template-columns:minmax(0,1fr) 280px;gap:22px}.ec96-article-related-grid{grid-template-columns:1fr}.ec96-article-card{display:flex}.ec96-article-card>img{width:120px;object-fit:cover}.ec96-article-sidebar>section{padding:18px}}
@media(max-width:760px){.ec96-article-wrap{width:calc(100% - 32px)}.ec96-article-layout{grid-template-columns:1fr}.ec96-article-heading{padding:24px 0}.ec96-article-paper{padding:20px}.ec96-article-cover{margin:-20px -20px 22px}.ec96-article-body{font-size:16px}.ec96-article-body h2{font-size:22px}.ec96-article-sidebar{margin-top:12px}.ec96-article-card>img{width:100px}.ec96-article-card>div{padding:14px}}
</style>
